const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

function parseAge(text) {
  const age = Number(text);
  if (Number.isNaN(age)) {
    throw new TypeError("age must be a number");
  }
  if (age < 0 || age > 150) {
    throw new RangeError("age must be 0 to 150");
  }
  return age;
}

for (const line of lines) {
  try {
    console.log(`age: ${parseAge(line)}`);
  } catch (error) {
    console.log(`${error.name}: ${error.message}`);
  }
}

steps.body:
`finally` runs after `try` and `catch` no matter what happened: success, a caught error, or an error that escapes. Use it for cleanup, such as closing a file or logging that a step ended. When an error escapes, `finally` runs first and then an outer `catch` receives it.

Catch only what you can handle. `error instanceof RangeError` is true when the error was made with `new RangeError`, so check the type and rethrow everything else:

```javascript harness
function handle(order) {
  if (order.qty < 1) {
    throw new RangeError(`bad quantity ${order.qty}`);
  }
  console.log(`${order.qty} x ${order.item}`);
}

const order = { item: "pen", qty: 0 };
{{code}}
```

```javascript
try {
  handle(order);
} catch (error) {
  if (error instanceof RangeError) {
    console.log("skipped");
  } else {
    throw error;
  }
} finally {
  console.log("closed");
}
```

Put an outer `try` around this one to catch what was rethrown. To add context, wrap the low-level error instead of rethrowing it as is: `throw new Error("cannot read order 3", { cause: error })`. The outer catch reads the original back from `error.cause`.

When you do not need the error object, leave out the binding:

```javascript
function isJson(text) {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
}
console.log(isJson("[1, 2]"), isJson("{oops")); // true false
```

Catching every error silently hides real bugs, so use that form only when any failure means the same thing, as it does here.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

function parseOrder(line) {
  const [item, qtyText] = line.trim().split(/\s+/);
  if (qtyText === undefined) {
    throw new TypeError("missing quantity");
  }
  const qty = Number(qtyText);
  if (!Number.isInteger(qty) || qty < 1) {
    throw new RangeError(`bad quantity ${qtyText}`);
  }
  return { item, qty };
}

try {
  for (const [i, line] of lines.entries()) {
    try {
      const order = parseOrder(line);
      console.log(`order ${i + 1}: ${order.qty} x ${order.item}`);
    } catch (error) {
      if (error instanceof RangeError) {
        console.log(`rejected: ${error.message}`);
      } else {
        throw new Error(`cannot read order ${i + 1}`, { cause: error });
      }
    } finally {
      console.log(`closed order ${i + 1}`);
    }
  }
  console.log("all orders read");
} catch (error) {
  console.log(`fatal: ${error.message} (cause: ${error.cause.name})`);
}

