const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

function loadConfig(text) {
  const config = JSON.parse(text);
  if (!Number.isInteger(config.port) || config.port < 1 || config.port > 65535) {
    throw new RangeError("port out of range");
  }
  return config;
}

try {
  for (const [i, line] of lines.entries()) {
    try {
      const config = loadConfig(line);
      console.log(`port: ${config.port}`);
    } catch (error) {
      if (error instanceof SyntaxError) {
        console.log("bad json");
      } else {
        throw new Error(`cannot load config ${i + 1}`, { cause: error });
      }
    } finally {
      console.log("done");
    }
  }
  console.log("all configs loaded");
} catch (error) {
  console.log(`fatal: ${error.message} (cause: ${error.cause.name})`);
}
